* { box-sizing: border-box; }
[hidden] { display: none !important; }
:root { color-scheme: light; --ink: #172b3a; --muted: #617481; --paper: #fffdf7; --line: #d9e3df; --mint: #bdf2d5; --coral: #ff806e; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 28px 16px; background-color: #172b3a; background-image: linear-gradient(45deg, #203b4b 25%, transparent 25%), linear-gradient(-45deg, #203b4b 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #203b4b 75%), linear-gradient(-45deg, transparent 75%, #203b4b 75%); background-size: 28px 28px; background-position: 0 0, 0 14px, 14px -14px, -14px 0; color: var(--ink); font: 16px/1.5 system-ui, sans-serif; }
.card { width: min(100%, 520px); padding: 34px clamp(22px, 7vw, 48px) 26px; background: var(--paper); border: 4px solid var(--ink); box-shadow: 8px 8px 0 #0c1b25; }
.brand-mark { display: grid; place-items: center; width: 44px; height: 44px; background: var(--mint); border: 3px solid var(--ink); font-size: 25px; }
.eyebrow, .footer-note { margin: 20px 0 5px; color: var(--muted); font-size: 12px; font-weight: 800; letter-spacing: .13em; }
h1 { margin: 0; font-size: clamp(26px, 6vw, 34px); line-height: 1.2; letter-spacing: -.04em; }
.intro, .summary-intro { margin: 9px 0 24px; color: var(--muted); }
.progress-wrap { margin: 25px 0 28px; }
.progress-label { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 9px; font-size: 14px; font-weight: 700; }
.progress-label span:last-child { color: var(--muted); }
.progress-track { height: 12px; overflow: hidden; border: 2px solid var(--ink); background: #e9efeb; }
.progress-fill { width: 33.333%; height: 100%; background: var(--coral); transition: width .2s ease; }
.step h2 { margin: 0 0 18px; font-size: 22px; }
.step > label:not(.plan-card) { display: block; margin: 15px 0 6px; font-weight: 700; }
input[type="text"], input[type="email"] { width: 100%; min-height: 50px; padding: 12px 14px; border: 2px solid #aabbb5; border-radius: 0; background: white; color: var(--ink); font: inherit; }
input::placeholder { color: #84949c; }
input:focus-visible, button:focus-visible, .plan-card:focus-within { outline: 3px solid var(--coral); outline-offset: 3px; }
.hint, .fine-print { margin: 10px 0 0; color: var(--muted); font-size: 14px; }
.actions { display: flex; justify-content: space-between; gap: 12px; margin-top: 27px; }
.button { min-height: 48px; padding: 10px 16px; border: 2px solid var(--ink); border-radius: 0; font: inherit; font-weight: 800; cursor: pointer; transition: transform .08s, box-shadow .08s, background-color .15s; }
.button:active:not(:disabled) { transform: translate(2px, 2px); box-shadow: none; }
.primary { background: var(--mint); color: var(--ink); box-shadow: 3px 3px 0 var(--ink); }
.primary:hover:not(:disabled) { background: #a4e9c2; }
.primary:disabled { opacity: .48; cursor: not-allowed; box-shadow: none; }
.secondary { background: white; color: var(--ink); box-shadow: 3px 3px 0 var(--ink); }
.secondary:hover { background: #edf4ef; }
.plans { display: grid; gap: 12px; margin: 0; padding: 0; border: 0; }
.plan-card { position: relative; display: flex; align-items: center; gap: 13px; min-height: 76px; padding: 14px; border: 2px solid var(--line); background: white; cursor: pointer; }
.plan-card:has(input:checked) { border-color: var(--ink); background: #effaf3; box-shadow: 3px 3px 0 var(--ink); }
.plan-card input { width: 19px; height: 19px; accent-color: var(--ink); flex: 0 0 auto; }
.plan-copy { display: grid; gap: 1px; flex: 1; }
.plan-copy strong, .price { font-size: 17px; }
.plan-copy small, .price small { color: var(--muted); font-size: 13px; }
.price { font-weight: 800; white-space: nowrap; }
.badge { position: absolute; top: -10px; right: 10px; padding: 1px 7px; background: var(--coral); border: 1px solid var(--ink); font-size: 10px; font-weight: 900; letter-spacing: .06em; }
.summary { margin: 19px 0 0; border-top: 2px solid var(--line); }
.summary div { display: flex; justify-content: space-between; gap: 18px; padding: 13px 0; border-bottom: 2px solid var(--line); }
.summary dt { color: var(--muted); font-weight: 700; }
.summary dd { max-width: 65%; margin: 0; overflow-wrap: anywhere; text-align: right; font-weight: 800; }
.success { text-align: center; padding-top: 8px; }
.success-icon { display: grid; place-items: center; width: 64px; height: 64px; margin: 0 auto 18px; border: 3px solid var(--ink); background: var(--mint); font-size: 32px; font-weight: 900; }
.success p { color: var(--muted); }
.success strong { color: var(--ink); }
.restart { margin-top: 18px; }
.form-message { min-height: 22px; margin: 8px 0 0; color: #963c32; font-size: 14px; font-weight: 700; }
.footer-note { margin: 25px 0 0; text-align: center; font-size: 10px; }
.footer-note span { color: var(--coral); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 390px) { .card { padding-inline: 18px; } .actions .button { padding-inline: 11px; font-size: 15px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; } }

const form = document.querySelector('#signup-form');
const steps = [...document.querySelectorAll('.step')];
const nextButtons = [...document.querySelectorAll('[data-next]')];
const progress = document.querySelector('.progress-track');
const progressFill = document.querySelector('#progress-fill');
const stepLabel = document.querySelector('#step-label');
const stepName = document.querySelector('#step-name');
const message = document.querySelector('#form-message');
let currentStep = 0;
const stepNames = ['Your details', 'Choose a plan', 'Review'];

function validDetails() {
  const name = form.elements.name;
  const email = form.elements.email;
  return name.value.trim().length >= 2 && email.validity.valid && email.value.trim() !== '';
}
function validPlan() { return Boolean(form.querySelector('input[name="plan"]:checked')); }
function updateNext() {
  nextButtons[0].disabled = !validDetails();
  nextButtons[1].disabled = !validPlan();
}
function showStep(index) {
  currentStep = index;
  steps.forEach((section, i) => { section.hidden = i !== index; });
  const shown = Math.min(index, 2);
  stepLabel.textContent = `Step ${shown + 1} of 3`;
  stepName.textContent = stepNames[shown];
  progress.setAttribute('aria-valuenow', String(shown + 1));
  progressFill.style.width = `${((shown + 1) / 3) * 100}%`;
  message.textContent = '';
  updateNext();
  const heading = steps[index].querySelector('h2');
  heading.setAttribute('tabindex', '-1');
  heading.focus();
}
function fillSummary() {
  document.querySelector('#summary-name').textContent = form.elements.name.value.trim();
  document.querySelector('#summary-email').textContent = form.elements.email.value.trim();
  document.querySelector('#summary-plan').textContent = form.querySelector('input[name="plan"]:checked').value;
}

form.addEventListener('input', updateNext);
form.addEventListener('change', updateNext);
nextButtons.forEach((button, index) => button.addEventListener('click', () => {
  if (index === 0 && validDetails()) showStep(1);
  if (index === 1 && validPlan()) { fillSummary(); showStep(2); }
}));
document.querySelectorAll('[data-back]').forEach(button => button.addEventListener('click', () => showStep(currentStep - 1)));
form.addEventListener('submit', event => {
  event.preventDefault();
  if (currentStep !== 2) return;
  document.querySelector('#confirmed-name').textContent = form.elements.name.value.trim();
  document.querySelector('#confirmed-email').textContent = form.elements.email.value.trim();
  document.querySelector('#confirmed-plan').textContent = form.querySelector('input[name="plan"]:checked').value;
  showStep(3);
  stepLabel.textContent = 'Complete';
  stepName.textContent = 'You’re all set';
  progress.setAttribute('aria-valuenow', '3');
});
document.querySelector('#restart').addEventListener('click', () => {
  form.reset();
  showStep(0);
  document.querySelector('#name').focus();
});
updateNext();
